import{_ as t,a as d,o as a,a6 as r}from"./chunks/framework.CJDy2q7X.js";const w=JSON.parse(`{"title":"File an EU Withdrawal","description":"","frontmatter":{"outline":false,"examples":[{"id":"create-eu-withdrawal","title":"File an EU Withdrawal","description":"File an EU right-of-withdrawal declaration against one of the authenticated customer's own orders.","query":"mutation CreateEuWithdrawal(\\n  $orderId: Int!\\n  $reasonText: String\\n) {\\n  createEuWithdrawal(\\n    input: {\\n      orderId: $orderId\\n      reasonText: $reasonText\\n    }\\n  ) {\\n    euWithdrawal {\\n      _id\\n      uuid\\n      orderId\\n      orderIncrementId\\n      isGuest\\n      customerEmail\\n      status\\n      reasonText\\n      receivedAt\\n      confirmationSentAt\\n      declinedAt\\n      declinedReason\\n      refundedAt\\n      refundNote\\n      createdAt\\n      updatedAt\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"orderId\\": 12,\\n  \\"reasonText\\": \\"Changed my mind.\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createEuWithdrawal\\": {\\n      \\"euWithdrawal\\": {\\n        \\"_id\\": 7,\\n        \\"uuid\\": \\"b2f1c0de-5a2e-4d7a-9f2e-3c1a2b4d5e6f\\",\\n        \\"orderId\\": 12,\\n        \\"orderIncrementId\\": \\"000000012\\",\\n        \\"isGuest\\": false,\\n        \\"customerEmail\\": \\"jane@example.com\\",\\n        \\"status\\": \\"received\\",\\n        \\"reasonText\\": \\"Changed my mind.\\",\\n        \\"receivedAt\\": \\"2026-07-20T09:00:00+00:00\\",\\n        \\"confirmationSentAt\\": \\"2026-07-20T09:00:05+00:00\\",\\n        \\"declinedAt\\": null,\\n        \\"declinedReason\\": null,\\n        \\"refundedAt\\": null,\\n        \\"refundNote\\": null,\\n        \\"createdAt\\": \\"2026-07-20T09:00:00+00:00\\",\\n        \\"updatedAt\\": \\"2026-07-20T09:00:05+00:00\\"\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"orderId required","cause":"The orderId field is missing","solution":"Provide the numeric ID of one of your own orders"},{"error":"NOT_FOUND","cause":"The order is not the customer's, or the channel does not have EU withdrawal enabled","solution":"File only against your own orders, and confirm the order's channel has EU withdrawal enabled — a disabled channel returns this same message"},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/eu-withdrawal/mutations/create-eu-withdrawal.md","filePath":"api/graphql-api/shop/eu-withdrawal/mutations/create-eu-withdrawal.md","lastUpdated":1787290888000}`),o={name:"api/graphql-api/shop/eu-withdrawal/mutations/create-eu-withdrawal.md"};function n(i,e,l,c,h,s){return a(),d("div",null,e[0]||(e[0]=[r('<h1 id="file-an-eu-withdrawal" tabindex="-1">File an EU Withdrawal <a class="header-anchor" href="#file-an-eu-withdrawal" aria-label="Permalink to &quot;File an EU Withdrawal&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>createEuWithdrawal</code> mutation records an EU right-of-withdrawal declaration against one of the authenticated customer&#39;s <strong>own</strong> orders and triggers the durable-medium confirmation email. The declaration is created with status <code>received</code>.</p><p>Filing is <strong>idempotent</strong> — a second call for the same order returns the existing declaration instead of creating a duplicate.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This mutation requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="the-channel-must-have-withdrawal-enabled" tabindex="-1">The channel must have withdrawal enabled <a class="header-anchor" href="#the-channel-must-have-withdrawal-enabled" aria-label="Permalink to &quot;The channel must have withdrawal enabled&quot;">​</a></h2><p>Filing only works when EU right of withdrawal is switched on for the channel the <strong>order</strong> belongs to. The setting is off by default. When it is off the mutation fails with the same not-found message an unknown order produces, so check the configuration before assuming the identifiers are wrong — see the <a href="/api/graphql-api/shop/eu-withdrawal/">overview</a>.</p><h2 id="input-fields" tabindex="-1">Input Fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>Int!</code></td><td>✅ Yes</td><td>The numeric ID of one of the customer&#39;s own orders.</td></tr><tr><td><code>reasonText</code></td><td><code>String</code></td><td>❌ No</td><td>An optional reason for withdrawing.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>euWithdrawal._id</code></td><td><code>Int!</code></td><td>Numeric declaration ID.</td></tr><tr><td><code>euWithdrawal.uuid</code></td><td><code>String!</code></td><td>Stable public identifier for the declaration.</td></tr><tr><td><code>euWithdrawal.orderId</code></td><td><code>Int!</code></td><td>Numeric ID of the order the withdrawal applies to.</td></tr><tr><td><code>euWithdrawal.orderIncrementId</code></td><td><code>String!</code></td><td>Human-readable order number.</td></tr><tr><td><code>euWithdrawal.isGuest</code></td><td><code>Boolean!</code></td><td>Whether the declaration was filed on a guest order.</td></tr><tr><td><code>euWithdrawal.customerEmail</code></td><td><code>String!</code></td><td>Email address tied to the declaration.</td></tr><tr><td><code>euWithdrawal.status</code></td><td><code>String!</code></td><td>Declaration status: <code>received</code>, <code>declined</code>, <code>refunded</code>.</td></tr><tr><td><code>euWithdrawal.reasonText</code></td><td><code>String</code></td><td>The reason the shopper supplied, or <code>null</code>.</td></tr><tr><td><code>euWithdrawal.receivedAt</code></td><td><code>DateTime</code></td><td>Timestamp when the declaration was received.</td></tr><tr><td><code>euWithdrawal.confirmationSentAt</code></td><td><code>DateTime</code></td><td>Timestamp when the confirmation email was sent, or <code>null</code>.</td></tr><tr><td><code>euWithdrawal.declinedAt</code></td><td><code>DateTime</code></td><td>Timestamp when the withdrawal was declined, or <code>null</code>.</td></tr><tr><td><code>euWithdrawal.declinedReason</code></td><td><code>String</code></td><td>Reason the store declined the withdrawal, or <code>null</code>.</td></tr><tr><td><code>euWithdrawal.refundedAt</code></td><td><code>DateTime</code></td><td>Timestamp when the order was refunded, or <code>null</code>.</td></tr><tr><td><code>euWithdrawal.refundNote</code></td><td><code>String</code></td><td>Note attached to the refund, or <code>null</code>.</td></tr><tr><td><code>euWithdrawal.createdAt</code></td><td><code>DateTime!</code></td><td>Declaration creation timestamp.</td></tr><tr><td><code>euWithdrawal.updatedAt</code></td><td><code>DateTime!</code></td><td>Declaration last update timestamp.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/eu-withdrawal/mutations/create-guest-eu-withdrawal.html">File a Guest Withdrawal</a></li><li><a href="/api/graphql-api/shop/eu-withdrawal/queries/list-eu-withdrawals.html">List EU Withdrawals</a></li><li><a href="/api/graphql-api/shop/eu-withdrawal/">EU Withdrawal Overview</a></li></ul>',14)]))}const m=t(o,[["render",n]]);export{w as __pageData,m as default};
